import * as T from 'three';
import {jointBones,jointNames,jointAngles,jointRange,jointQuaternion,limitJoint,mirrorPose} from './joint-pose.js?v=20261025-release1';
export function setupPoseControls(g){
 const e=g.editor,surface=e.renderer.domElement,box=document.createElement('section');box.className='pose-joint-controls';box.setAttribute('aria-label','선택 부위 포즈 조절');g.toolbar.after(box);
 box.innerHTML='<strong id=posePartName>인물 포즈</strong><label><input id=poseLimits type=checkbox checked>관절 가동 범위 제한</label><div class=pose-angles></div><div class=pose-actions><button id=poseLock>선택 부위 잠금</button><button id=poseResetPart>선택 부위 초기화</button><button id=poseUnlock>잠금 모두 해제</button><button id=poseMirrorL>왼쪽 → 오른쪽</button><button id=poseMirrorR>오른쪽 → 왼쪽</button></div><details><summary>포즈집 · 내 포즈</summary><div class=pose-actions><button data-base=stand>서기</button><button data-base=sit>앉기</button><button data-base=walk>걷기</button><button data-base=reach>뻗기</button></div><label>포즈 이름<input id=poseSaveName placeholder="예: 대화하며 왼쪽 보기" maxlength=40></label><button id=poseSave>현재 포즈 저장</button><label>내 포즈<select id=poseSaved></select></label><button id=poseLoad>포즈 적용</button><button id=poseRemove>선택 포즈 삭제</button></details><small>보라색 부위를 끌어 조절 · 손/발: 이동 · R: 손바닥/발목 회전 · Esc: 취소</small>';
 const $=id=>box.querySelector('#'+id),person=()=>e.state?.people[e.index],rig=()=>e.figures.children[e.index]?.userData.motionRig;
 let library=[];try{const value=JSON.parse(localStorage.getItem('scroll-pose-library')||'[]');if(Array.isArray(value))library=value.slice(0,100);}catch{}
 const list=()=>{$('poseSaved').replaceChildren(...library.map((p,i)=>new Option(p.name,String(i))));};list();
 const saveLibrary=()=>{localStorage.setItem('scroll-pose-library',JSON.stringify(library));list();};
 const commit=()=>{e.updatePerson({pose:true});e.controlsUI();sync();e.transformCommit=true;e.flush();};
 const angles=['앞뒤 굽힘','좌우 돌리기','옆으로 기울기'].map((label,i)=>{const row=document.createElement('label'),input=document.createElement('input'),out=document.createElement('output');row.append(label,input,out);input.type='range';input.step=1;input.setAttribute('aria-label',label);box.querySelector('.pose-angles').append(row);input.oninput=()=>{const p=person(),r=rig();if(!p||!jointBones[g.part]||p.jointLocks?.[g.part])return;p.joints||={};p.joints[g.part]=jointQuaternion(r,g.part,angles.map(a=>+a.input.value),p.jointLimits!==false).toArray();e.updatePerson({pose:true});out.textContent=input.value+'°';};input.onchange=commit;return {row,input,out};});
 $('poseLimits').onchange=()=>{if(person()){person().jointLimits=$('poseLimits').checked;commit();}};
 $('poseLock').onclick=()=>{const p=person();if(!p||g.part==='whole')return;p.jointLocks||={};if(p.jointLocks[g.part])delete p.jointLocks[g.part];else{p.jointLocks[g.part]=true;const local=e.figures.children[e.index].userData.landmarks[g.part];if(/Hand|Foot/.test(g.part)&&local){p.targets||={};p.targets[g.part]=local.slice();}}commit();};
 $('poseResetPart').onclick=()=>{const p=person();if(!p)return;delete p.joints?.[g.part];delete p.targets?.[g.part];delete p.jointLocks?.[g.part];commit();};
 $('poseUnlock').onclick=()=>{if(person()){delete person().jointLocks;commit();}};
 for(const [id,side]of [['poseMirrorL','left'],['poseMirrorR','right']])$(id).onclick=()=>{if(person()&&rig()){mirrorPose(person(),rig(),side);commit();}};
 for(const button of box.querySelectorAll('[data-base]'))button.onclick=()=>{const p=person();if(!p)return;p.pose=button.dataset.base;for(const key of ['joints','targets','motionPose','hands','fingers','jointLocks'])delete p[key];commit();};
 $('poseSave').onclick=()=>{const p=person(),name=$('poseSaveName').value.trim();if(!p||!name)return;const pose={};for(const key of ['pose','joints','targets','motionPose','hands','fingers','jointLimits'])if(p[key]!==undefined)pose[key]=structuredClone(p[key]);const i=library.findIndex(v=>v.name===name);if(i>=0)library[i]={name,pose};else library.push({name,pose});library=library.slice(-100);saveLibrary();};
 $('poseLoad').onclick=()=>{const p=person(),saved=library[+$('poseSaved').value];if(!p||!saved)return;for(const key of ['joints','targets','motionPose','hands','fingers','jointLocks'])delete p[key];Object.assign(p,structuredClone(saved.pose));commit();};
 $('poseRemove').onclick=()=>{library.splice(+$('poseSaved').value,1);saveLibrary();};
 function sync(){const p=person(),r=rig();box.hidden=!p||!!e.movement?.active;if(!p||!r)return;$('posePartName').textContent=jointNames[g.part]||({leftHand:'왼손 이동',rightHand:'오른손 이동',leftFoot:'왼발 이동',rightFoot:'오른발 이동'})[g.part]||'인물 전체';$('poseLimits').checked=p.jointLimits!==false;$('poseLock').disabled=g.part==='whole';$('poseLock').textContent=p.jointLocks?.[g.part]?'선택 부위 잠금 해제':'선택 부위 잠금';const enabled=!!jointBones[g.part],values=enabled?jointAngles(r,g.part,r.bones[jointBones[g.part]].quaternion):[],ranges=jointRange(g.part);for(const [i,a]of angles.entries()){a.row.hidden=!enabled;a.input.min=p.jointLimits===false?-180:ranges[i][0];a.input.max=p.jointLimits===false?180:ranges[i][1];a.input.value=Math.round(values[i]||0);a.input.disabled=!!p.jointLocks?.[g.part];a.out.textContent=Math.round(values[i]||0)+'°';}}
 let drag;
 surface.addEventListener('pointerdown',ev=>{if(ev.button!==0||ev.altKey||e.movement?.active)return;const rect=surface.getBoundingClientRect(),ray=new T.Raycaster();ray.setFromCamera(new T.Vector2((ev.clientX-rect.left)/rect.width*2-1,-(ev.clientY-rect.top)/rect.height*2+1),e.camera);const hit=ray.intersectObjects(e.figures.children,true).find(h=>h.object.userData.poseMarker&&h.object.visible);if(!hit)return;let f=hit.object;while(f&&f.userData.person===undefined)f=f.parent;if(!f)return;e.index=f.userData.person;g.part=hit.object.userData.part;document.getElementById('jointSelect').value=g.part;g.setMode(jointBones[g.part]?'rotate':'translate');const p=person();sync();ev.preventDefault();ev.stopImmediatePropagation();surface.focus({preventScroll:true});if(p.jointLocks?.[g.part])return;const point=f.localToWorld(new T.Vector3(...f.userData.landmarks[g.part])),normal=e.camera.getWorldDirection(new T.Vector3()),plane=new T.Plane().setFromNormalAndCoplanarPoint(normal,point),start=ray.ray.intersectPlane(plane,new T.Vector3());if(!start)return;drag={id:ev.pointerId,x:ev.clientX,y:ev.clientY,point,plane,start,before:structuredClone(p),q:jointBones[g.part]?f.userData.motionRig.bones[jointBones[g.part]].getWorldQuaternion(new T.Quaternion()):null,moved:false};g.directDragging=true;g.transform.detach();e.controls.enabled=false;surface.setPointerCapture(ev.pointerId);},true);
 surface.addEventListener('pointermove',ev=>{if(!drag||ev.pointerId!==drag.id)return;ev.preventDefault();ev.stopImmediatePropagation();const dx=ev.clientX-drag.x,dy=ev.clientY-drag.y;if(Math.hypot(dx,dy)<2&&!drag.moved)return;drag.moved=true;const p=person(),f=e.figures.children[e.index],r=f.userData.motionRig,speed=ev.shiftKey?.002:.01;if(drag.q){let change;if(/Elbow|Knee/.test(g.part)){const values=jointAngles(r,g.part,new T.Quaternion(...(drag.before.joints?.[g.part]||r.base[jointBones[g.part]].toArray())));values[0]+=dy*speed*60;change=jointQuaternion(r,g.part,values,p.jointLimits!==false);}else{const right=new T.Vector3(1,0,0).applyQuaternion(e.camera.quaternion),up=new T.Vector3(0,1,0).applyQuaternion(e.camera.quaternion),world=new T.Quaternion().setFromAxisAngle(up,dx*speed).multiply(new T.Quaternion().setFromAxisAngle(right,dy*speed)).multiply(drag.q);change=r.bones[jointBones[g.part]].parent.getWorldQuaternion(new T.Quaternion()).invert().multiply(world);change=limitJoint(r,g.part,change,p.jointLimits!==false);}p.joints||={};p.joints[g.part]=change.toArray();}else{const rect=surface.getBoundingClientRect(),ray=new T.Raycaster();ray.setFromCamera(new T.Vector2((ev.clientX-rect.left)/rect.width*2-1,-(ev.clientY-rect.top)/rect.height*2+1),e.camera);const point=ray.ray.intersectPlane(drag.plane,new T.Vector3());if(point){p.targets||={};p.targets[g.part]=f.worldToLocal(drag.point.clone().add(point.sub(drag.start))).toArray();}}e.updatePerson({pose:true});sync();},true);
 function finish(cancel=false){if(!drag)return;const prev=drag;drag=null;if(cancel)e.state.people[e.index]=prev.before;g.directDragging=false;e.controls.enabled=true;g.dragFinished=performance.now();if(surface.hasPointerCapture(prev.id))surface.releasePointerCapture(prev.id);e.updatePerson({pose:true});g.sync();sync();if(prev.moved&&!cancel){e.transformCommit=true;e.flush();}}
 surface.addEventListener('pointerup',ev=>{if(drag){ev.stopImmediatePropagation();finish();}},true);surface.addEventListener('pointercancel',()=>finish(true),true);surface.addEventListener('keydown',ev=>{if(drag&&ev.key==='Escape'){ev.preventDefault();ev.stopImmediatePropagation();finish(true);}},true);surface.addEventListener('lostpointercapture',()=>finish(true));window.addEventListener('blur',()=>finish(true));
 return {sync};
}
